'use strict';
/**
 * 解读规则层 —— 三体系取象 → 共同维度信号
 * ============================================================
 * 【本文件的性质，务必先读】
 *
 * 上面 lib/bazi.js / ziwei.js / astro.js 算的是【事实】：天文位置、历法干支、
 * 星曜落宫。那些是可验证的确定性计算。
 *
 * 本文件做的是【取象】：把事实映射到性格/倾向描述。这一步是
 * **传统约定**，不是经过实证校准的预测模型。我们把它写成显式的规则表
 * （而不是让 LLM 自由发挥），理由是：
 *   1. 可审计 —— 每条结论都能追溯到具体规则和经典出处
 *   2. 可复现 —— 同一张盘每次得到同样的信号
 *   3. 可争论 —— 规则写出来了，懂行的人可以指出哪条不对
 *
 * 出处标注：八字引《渊海子平》《滴天髓》《子平真诠》，
 *   紫微引《紫微斗数全书》，占星引托勒密《四书》与四元素传统说。
 *   这些是"该说法在传统中的依据"，不是"该说法正确"的证明。
 */

/* ==================================================================
 * 一、共同维度定义
 * ================================================================== */

const { CALIBRATION, Z_THRESHOLD, Z_FULL_STRENGTH } = require('./calibration.js');

const DIMENSIONS = [
  {
    key: 'action', name: '行动取向',
    positive: '主动出击', negative: '蓄势待发',
    question: '碰到机会，你是先动起来、边做边看，还是先摸清底细再动？',
  },
  {
    key: 'resource', name: '资源取向',
    positive: '务实经营', negative: '意义优先',
    question: '做一件事，你更在意它能带来什么，还是它对你意味着什么？',
  },
  {
    key: 'expression', name: '表达取向',
    positive: '外放表达', negative: '内敛沉淀',
    question: '你的想法更习惯直接说出来，还是先在心里放熟？',
  },
  {
    key: 'structure', name: '结构取向',
    positive: '依循规则', negative: '突破常规',
    question: '面对既有的路径和规则，你倾向于遵守，还是改写？',
  },
  {
    key: 'risk', name: '风险偏好',
    positive: '敢冒风险', negative: '稳健求安',
    question: '在更大收益和更高确定性之间，你天然偏向哪一边？',
  },
];

const DIM_BY_KEY = Object.fromEntries(DIMENSIONS.map((d) => [d.key, d]));

/* ------------------------------------------------------------------
 * 标准化：原始 Δ → z 值
 *
 * 三个体系的原始 Δ 分布差异极大（标准差 0.19 / 0.64 / 0.50，差三倍），
 * 用同一个绝对阈值就会出现"紫微对所有盘都说话、八字几乎不说话"。
 * 统一做 z = (Δ − μ) / σ，μ σ 由 test/gen.calibration.js 实测生成
 * （见 lib/calibration.js），阈值改为以标准差为单位，三家的
 * 触发灵敏度与强度才可比。
 *
 * 注意：紫微的 Δ 是【双峰】分布 —— 十四主星相对位置由"命宫+五行局"
 * 决定，配置空间本就有限，所以它要么明确说"主动"、要么明确说"蓄势"，
 * 很少中立。这是该体系的性质，不是缺陷；我们不人为拉平它的触发率。
 * ------------------------------------------------------------------ */
function zScore(system, dim, delta) {
  const c = CALIBRATION[system] && CALIBRATION[system][dim];
  if (!c || !c.sd) return 0;
  return (delta - c.mean) / c.sd;
}
/** z 值 → 信号强度 [0,1] */
function strengthOf(z) {
  return +Math.min(Math.abs(z) / Z_FULL_STRENGTH, 1).toFixed(3);
}

/* ==================================================================
 * 二、八字取象规则
 * ================================================================== */

/**
 * 依据：十神结构占比（十神是"日主与其他干支的关系"，是子平法的核心分类）。
 *
 *   比劫 = 与我同类 → 自主、竞争、主动
 *   食伤 = 我所生   → 输出、表达、创造
 *   财星 = 我所克   → 资源、务实、结果
 *   官杀 = 克我者   → 约束、规则、压力
 *   印星 = 生我者   → 吸收、内敛、依托
 *
 * 每条规则写成 [维度, 加分项, 减分项, 出处]，
 * 加分项总和 − 减分项总和 = 该维度的倾向分数。
 */
const BAZI_RULES = [
  {
    dim: 'action',
    pos: ['比劫', '食伤'], neg: ['官杀', '印星'],
    basis: '比劫食伤主"我主动"，官杀印星主"我受制"',
    citation: '《子平真诠·论用神》',
  },
  {
    dim: 'resource',
    pos: ['财星'], neg: ['印星'],
    basis: '财为我所克，主资源与结果；印为生我者，主吸收与内在价值',
    citation: '《滴天髓·论财》',
  },
  {
    dim: 'expression',
    pos: ['食伤'], neg: ['印星'],
    basis: '食伤为输出之神，印为收纳之神',
    citation: '《渊海子平·论食神伤官》',
  },
  {
    dim: 'structure',
    pos: ['正官', '正印'], neg: ['伤官', '劫财'],
    basis: '正官正印主循规守序；伤官劫财主越界破格',
    citation: '《渊海子平·论伤官》',
  },
  {
    dim: 'risk',
    pos: ['七杀', '劫财'], neg: ['正印', '正财'],
    basis: '七杀劫财主进取与争夺；正印正财主护持与积累',
    citation: '《三命通会·论七杀》',
  },
];

function baziSignals(b) {
  // 用 pctAll：它同时含单神（正官/伤官…）与分组（比劫/官杀…），
  // 且同分母，规则表可以自由混用两者。
  const pct = (b.godDetail && (b.godDetail.pctAll || b.godDetail.pct)) || {};
  const sum = (arr) => arr.reduce((a, k) => a + (pct[k] || 0), 0);
  const out = [];

  BAZI_RULES.forEach((r) => {
    const pos = sum(r.pos);
    const neg = sum(r.neg);
    const delta = (pos - neg) / 100;
    const z = zScore('bazi', r.dim, delta);
    if (Math.abs(z) < Z_THRESHOLD) return;
    out.push({
      system: '八字',
      dim: r.dim,
      dir: Math.sign(delta),
      z: +z.toFixed(3),
      strength: strengthOf(z),
      basis: r.basis,
      citation: r.citation,
      detail: `${r.pos.join('+')} ${pos.toFixed(1)}% ↔ ${r.neg.join('+')} ${neg.toFixed(1)}%`,
    });
  });

  return out;
}

/* ==================================================================
 * 三、紫微取象规则
 * ================================================================== */

/**
 * 十四主星的四大类型（紫微斗数通行分类，非本实现自创）：
 *   开创型：七杀 破军 廉贞 贪狼   —— 行动力强、不守旧
 *   领导型：紫微 天府 武曲 天相   —— 重结构、能掌事
 *   支援型：太阳 巨门 天机       —— 外向、善传播与策划
 *   合作型：太阴 天梁 天同       —— 温和、重关系、求稳
 */
const STAR_CATEGORY = {
  七杀: '开创', 破军: '开创', 廉贞: '开创', 贪狼: '开创',
  紫微: '领导', 天府: '领导', 武曲: '领导', 天相: '领导',
  太阳: '支援', 巨门: '支援', 天机: '支援',
  太阴: '合作', 天梁: '合作', 天同: '合作',
};

/** 星曜亮度权重：庙旺者力强，落陷者力弱 */
const BRIGHTNESS = { 庙: 1.0, 旺: 0.9, 得: 0.75, 利: 0.65, 平: 0.55, 不: 0.45, 陷: 0.35 };

/**
 * 各维度上四类星的【带符号权重】。
 *
 * 为什么不用「正类 / (正类+负类)」这种比值：
 *   早期版本把星分成"加分/减分"两组算比值，结果 领导型 星两边都不进，
 *   分母经常为 0，Δ 直接恒等于 1 —— 校准发现三条规则的触发率是 100%，
 *   即对所有盘说同一句话，等于没写。
 * 现在改成：每类星在每个维度上都有一个确定分数，Δ = 加权平均。
 * 这样取值连续、有界，且每颗星都参与。
 */
const ZIWEI_SIGN = {
  action:     { 开创: +1.0, 领导: +0.15, 支援: -0.40, 合作: -1.0 },
  resource:   { 领导: +1.0, 开创: +0.10, 支援: -0.50, 合作: -0.50 },
  expression: { 支援: +1.0, 开创: +0.30, 领导: +0.10, 合作: -1.0 },
  structure:  { 领导: +1.0, 合作: +0.40, 支援: +0.10, 开创: -1.0 },
  risk:       { 开创: +1.0, 领导: +0.10, 支援: -0.20, 合作: -1.0 },
};

/** 每个维度对应的取象依据与出处 */
const ZIWEI_BASIS = {
  action:     ['杀破狼主开创变动；月梁同主守成待时', '《紫微斗数全书·论命宫》'],
  resource:   ['紫府武相主掌资源与实务；日巨机主信息与理想', '《紫微斗数全书·论财帛官禄》'],
  expression: ['太阳巨门主外显传播；太阴天同主内敛含蓄', '《紫微斗数全书·论命身宫》'],
  structure:  ['紫微天相重体制与秩序；破军贪狼破格求变', '《紫微斗数全书·论星曜性情》'],
  risk:       ['七杀破军敢冲敢赌；天梁天同趋稳避险', '《紫微斗数全书·论杀破狼》'],
};

/**
 * 取命宫 + 三方四正范围内的主星。
 * 为什么含三方四正：紫微斗数看命，从不只看命宫一宫，
 * 三方四正（财帛/官禄/迁移）共同决定格局，这是本门基本法。
 */
function collectZiweiStars(z) {
  const zones = [
    z.sanFangSiZheng.benGong,
    z.sanFangSiZheng.caiBo,
    z.sanFangSiZheng.guanLu,
    z.sanFangSiZheng.qianYi,
  ];
  const stars = [];
  zones.forEach((zone) => {
    (zone.majorStars || []).forEach((s) => {
      stars.push({
        name: s.name,
        category: STAR_CATEGORY[s.name] || null,
        weight: BRIGHTNESS[s.brightness] ?? 0.55,
        brightness: s.brightness,
        mutagen: s.mutagen,
        palace: zone.name,
      });
    });
  });
  return stars;
}

function ziweiSignals(z) {
  const stars = collectZiweiStars(z).filter((s) => s.category);
  if (!stars.length) return [];

  const totalW = stars.reduce((a, s) => a + s.weight, 0);
  const out = [];

  DIMENSIONS.forEach((d) => {
    const sign = ZIWEI_SIGN[d.key];
    if (!sign) return;
    const num = stars.reduce((a, s) => a + (sign[s.category] || 0) * s.weight, 0);
    const delta = totalW > 0 ? num / totalW : 0;
    const z = zScore('ziwei', d.key, delta);
    if (Math.abs(z) < Z_THRESHOLD) return;
    const [basis, citation] = ZIWEI_BASIS[d.key];
    out.push({
      system: '紫微',
      dim: d.key,
      dir: Math.sign(delta),
      z: +z.toFixed(3),
      strength: strengthOf(z),
      basis,
      citation,
      detail: stars.map((s) => `${s.name}(${s.category}${s.brightness || ''})`).join(' '),
    });
  });

  return out;
}

/* ==================================================================
 * 四、西方占星取象规则
 * ================================================================== */

/**
 * 四元素（托勒密《四书》传统）：
 *   火 —— 热而干，主动、外扩、直觉
 *   土 —— 冷而干，务实、稳定、感官
 *   风 —— 热而湿，思维、交流、社会
 *   水 —— 冷而湿，情感、共情、内省
 * 三模式：
 *   基本 —— 发起；固定 —— 维持；变动 —— 适应
 */

const OUTGOING_SIGNS = new Set(['白羊', '双子', '狮子', '天秤', '射手', '水瓶']);
const RESERVED_SIGNS = new Set(['金牛', '巨蟹', '处女', '天蝎', '摩羯', '双鱼']);

/**
 * 个人点加权：太阳 / 月亮 / 上升 权重 2，其余行星权重 1。
 * 依据：古典占星里这三者最贴近"这个人本身"，其余行星更多描述
 *   具体领域（水星=思维、金星=关系、火星=行动方式…）。
 * 副作用（也是我们要的）：总权重从 8 变成 11，取值粒度更细，
 *   不会出现"要么 0 要么 1"的跳变。
 */
const ASTRO_POINT_WEIGHT = { 太阳: 2, 月亮: 2, 上升: 2 };

/** 按加权统计元素与模式的占比（各合计 100） */
function astroShares(a) {
  const all = a.bodies.concat([a.ascendant]);
  const el = { 火: 0, 土: 0, 风: 0, 水: 0 };
  const mo = { 基本: 0, 固定: 0, 变动: 0 };
  let tot = 0;
  all.forEach((p) => {
    const w = ASTRO_POINT_WEIGHT[p.name] || 1;
    el[p.element] += w;
    mo[p.mode] += w;
    tot += w;
  });
  Object.keys(el).forEach((k) => { el[k] = el[k] / tot * 100; });
  Object.keys(mo).forEach((k) => { mo[k] = mo[k] / tot * 100; });
  return { el, mo, total: tot };
}

/**
 * 各维度的连续打分式。
 * 统一形式：两个方向占比之差 ÷ 100，落在 [−1, 1]，
 * 再用 0.6 的混合系数把元素与模式两个来源合起来。
 * 这样取值连续，不会像"是否属于外向星座"那样非 0 即 1。
 */
function astroScore(a) {
  const { el, mo } = astroShares(a);
  const sun = a.sun, asc = a.ascendant, moon = a.moon;
  // 日月升三点的内外向占比（火风外向 / 水土内向）
  const pt = [sun, moon, asc];
  const outPt = pt.filter((p) => OUTGOING_SIGNS.has(p.sign)).length;
  const resPt = pt.filter((p) => RESERVED_SIGNS.has(p.sign)).length;

  return {
    action:     ((el.火 - el.水) + 0.6 * (mo.基本 - mo.变动)) / 100,
    resource:   ((el.土 - (el.风 + el.水) / 2)) / 100,
    expression: ((outPt - resPt) / 3 * 0.7 + (el.火 + el.风 - el.水 - el.土) / 100 * 0.3),
    structure:  ((el.土 + mo.固定) / 2 - mo.变动) / 100,
    risk:       ((el.火 + mo.基本) / 2 - (el.土 + mo.固定) / 2) / 100,
  };
}

const ASTRO_BASIS = {
  action:     ['火象与基本宫主发起外扩；水象与变动宫主感受与适应', '托勒密《四书》卷一·论元素'],
  resource:   ['土象主物质、积累与可握持之物', '托勒密《四书》卷一·论元素'],
  expression: ['太阳月亮上升共指对外呈现方式；火风主动外显，水土偏收敛', '托勒密《四书》卷三·论命主'],
  structure:  ['固定宫与土象主维持既有结构；变动宫主改写与适应', '托勒密《四书》卷一·论模式'],
  risk:       ['木星主扩张冒险，土星主限制与保守', '托勒密《四书》卷二·论吉凶星'],
};

function astroSignals(a) {
  const sc = astroScore(a);
  const { el, mo } = astroShares(a);
  const jup = a.bodies.find((x) => x.name === '木星');
  const sat = a.bodies.find((x) => x.name === '土星');
  const detailOf = {
    action: `火${el.火.toFixed(0)}% 水${el.水.toFixed(0)}% 基本${mo.基本.toFixed(0)}% 变动${mo.变动.toFixed(0)}%`,
    resource: `土${el.土.toFixed(0)}% 风${el.风.toFixed(0)}% 水${el.水.toFixed(0)}%`,
    expression: `太阳${a.sun.sign} 月亮${a.moon.sign} 上升${a.ascendant.sign}`,
    structure: `土${el.土.toFixed(0)}% 固定${mo.固定.toFixed(0)}% 变动${mo.变动.toFixed(0)}%`,
    risk: `木星${jup ? jup.sign : '—'} 土星${sat ? sat.sign : '—'} 火${el.火.toFixed(0)}% 土${el.土.toFixed(0)}%`,
  };

  const out = [];
  DIMENSIONS.forEach((d) => {
    const v = sc[d.key];
    if (v === undefined) return;
    const z = zScore('astro', d.key, v);
    if (Math.abs(z) < Z_THRESHOLD) return;
    const [basis, citation] = ASTRO_BASIS[d.key];
    out.push({
      system: '占星',
      dim: d.key,
      dir: Math.sign(v),
      z: +z.toFixed(3),
      strength: strengthOf(z),
      basis, citation,
      detail: detailOf[d.key],
    });
  });
  return out;
}

/* ==================================================================
 * 五、印证引擎
 * ================================================================== */

/**
 * 印证的核心逻辑（一句话）：
 *   三个体系用完全不同的方法推导 —— 八字用历法干支与五行生克，
 *   紫微用星曜落宫，占星用天文位置与元素 —— 如果它们指向同一结论，
 *   那这个结论不太可能是某个体系自身的系统性偏差造成的。
 *
 * 但必须同时说清印证的边界：
 *   三者共享同一套"取象→性格"的思维习惯（都源于古代宇宙观），
 *   所以它们的一致【部分】来自真实的信号，【部分】来自共同的先验。
 *   因此印证提升的是"相对可信度"，不是"绝对准确性"。
 *   不一致也不是错误，而往往是"这个人本身是情境依赖的"。
 */

/**
 * 一致程度标签。
 *
 * 【重要】这里刻意不用"可信度""准确率"这类词。
 *   原因见下方 VALIDITY —— 实测三体系两两一致率约 49%，
 *   与随机基线（50%）无显著差异。也就是说：
 *   "两个体系说法一致"【不能】推出"这个说法更可能为真"。
 *   一致只说明"同一个说法被两套不同的语言描述出来了"，
 *   它的价值是作为自省切入点更好用，不是预测更准。
 *   用"可信度高"这种标签就是在做无依据的宣称。
 */
const AGREEMENT_LABEL = {
  converge: '多体系共识',
  diverge: '体系分歧',
  single: '单体系所见',
  none: '无倾向',
};

const VERDICT_LABEL = {
  converge: '印证',
  diverge: '相左',
  single: '孤证',
  none: '无信号',
};

/**
 * 有效性声明 —— 随每次输出一起返回，不可省略。
 * 数据来自 test/verify.diagnostic.js（600 组随机盘）与阳性对照。
 */
const VALIDITY = {
  measured: {
    pairwiseAgreement: 0.484,
    randomBaseline: 0.5,
    positiveControl: 1.0,
    samples: 600,
  },
  method: 'test/verify.diagnostic.js',
  positiveControlNote: '阳性对照：构造一条两体系必然读同一字段的维度（时支阴阳），'
    + '测得一致率 100%，证明测量工具本身有效 —— 因此下面的 ~48% 是真实结果，不是脚本缺陷。',
  interpretation: '三个体系在当前 5 条共同维度上的读数在统计上相互独立，'
    + '两两一致率 48.4% 与随机基线 50% 无显著差异。',
  therefore: [
    '不能声称"多体系互证提高了准确率" —— 实测不支持这个说法。',
